(assert (= "1.12.6" (clojure-version)))
(prn (let [f (fn [n] n) values (eval (list 'vector f f))] [(identical? f (first values)) (identical? (first values) (second values)) ((first values) 42)]))
(prn (let [f (fn [n] n)] (eval (list 'do (list 'def 'review-prior-function f) (list 'identical? 'review-prior-function f)))))
(prn (do (def review-top-effects (atom [])) (let [x 1 f (fn [] x)] (try (eval (list 'do '(swap! review-top-effects conj :prefix) (list f))) (catch Throwable e nil))) @review-top-effects))
(prn (do (def review-unit-effects (atom [])) (let [x 1 f (fn [] x)] (try (eval (list 'let [] (list 'do '(swap! review-unit-effects conj :body) (list f)))) (catch Throwable e nil))) @review-unit-effects))
(prn (let [a (atom 0) f (fn [] (swap! a inc))] [(try (eval (list f)) (catch Throwable e :error)) @a]))
(prn (do (eval '(defmacro review-context [] (str *math-context*))) (let [v (eval '(var review-context))] [(with-precision 3 :rounding DOWN (v nil nil)) (v nil nil) (with-precision 9 :rounding CEILING (v nil nil)) (v nil nil)])))
(prn (do (eval '(defmacro review-context-error [fail] (if fail (throw (ex-info "context error" {})) (str *math-context*)))) (let [v (eval '(var review-context-error))] [(with-precision 3 (try (v nil nil true) (catch Throwable e :error))) (v nil nil false)])))
(prn (do (eval '(defmacro review-context-nil [] (nil? *math-context*))) (let [v (eval '(var review-context-nil))] [(v nil nil) (with-precision 0 (v nil nil)) (v nil nil)])))
